css:
#loader-12 {
  width: 60px;
  height: 25px;
  border: 2px solid;
  box-sizing: border-box;
  border-radius: 50%;
  display: grid;
  animation: l2 2s infinite linear;
}
#loader-12::before,
#loader-12::after {
  content: "";
  grid-area: 1/1;
  border: inherit;
  border-radius: 50%;
  animation: inherit;
  animation-duration: 3s;
}
#loader-12::after {
  --s: -1;
}
@keyframes l2 {
  100% {transform: rotate(calc(var(--s, 1) * 1turn))}
}
